   198	function isActionOfType<T extends ReportActionName[]>(
   199	    action: OnyxInputOrEntry<ReportAction>,
   200	    ...actionNames: T
   201	): action is {
   202	    [K in keyof T]: ReportAction<T[K]>;
   203	}[number] {
