   205	
   206	    // This is purely a performance optimization to limit the 'includes()' calls on Hermes
   207	    for (const i of actionNames) {
   208	        if (i === actionName) {
   209	            return true;
   210	        }
   211	    }
   212	
   213	    return false;
   214	}
