   216	function getOriginalMessage<T extends ReportActionName>(reportAction: OnyxInputOrEntry<ReportAction<T>>): OriginalMessage<T> | undefined {
   217	    if (!Array.isArray(reportAction?.message)) {
   218	        // eslint-disable-next-line deprecation/deprecation
   219	        return reportAction?.message ?? reportAction?.originalMessage;
   220	    }
   221	    // eslint-disable-next-line deprecation/deprecation
   222	    return reportAction.originalMessage;
   223	}
