   229	/**
   230	 * We are in the process of deprecating reportAction.originalMessage and will be setting the db version of "message" to reportAction.message in the future see: https://github.com/Expensify/App/issues/39797
   231	 * In the interim, we must check to see if we have an object or array for the reportAction.message, if we have an array we will use the originalMessage as this means we have not yet migrated.
   232	 */
   233	function getWhisperedTo(reportAction: OnyxInputOrEntry<ReportAction>): number[] {
   234	    if (!reportAction) {
   235	        return [];
   236	    }
   237	    const originalMessage = getOriginalMessage(reportAction);
   238	    const message = getReportActionMessage(reportAction);
   239	
   240	    if (!(originalMessage && typeof originalMessage === 'object' && 'whisperedTo' in originalMessage) && !(message && typeof message === 'object' && 'whisperedTo' in message)) {
   241	        return [];
   242	    }
   243	
   244	    if (message !== null && !Array.isArray(message) && typeof message === 'object' && 'whisperedTo' in message) {
   245	        return message?.whisperedTo ?? [];
   246	    }
   247	
   248	    if (originalMessage && typeof originalMessage === 'object' && 'whisperedTo' in originalMessage) {
   249	        return originalMessage?.whisperedTo ?? [];
   250	    }
   251	
   252	    if (typeof originalMessage !== 'object') {
   253	        Log.info('Original message is not an object for reportAction: ', true, {
   254	            reportActionID: reportAction?.reportActionID,
   255	            actionName: reportAction?.actionName,
   256	        });
   257	    }
   258	
   259	    return [];
   260	}
